const $=s=>document.querySelector(s),field=$('#message'),urlField=$('#url'),result=$('#result'),button=$('#scan-button'),form=$('#check-form'),error=$('#error');
let lang='en',mode='message',model=null,last=null,liveTimer=null,lastLiveValue='';
const localized=()=>({...copy[lang],...extraCopy[lang]});
const linkExamples={fake:{label:'Fake USCIS login',url:'http://uscis-gov.secure-login.example.xyz/account/verify'},short:{label:'Short link',url:'https://bit.ly/visa-update'},official:{label:'Official USCIS page',url:'https://www.uscis.gov/avoid-scams'}};
fetch('./model.json').then(r=>r.ok?r.json():null).then(data=>{model=data;}).catch(()=>{model=null;});
const node=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;};
function enhanceDemoPath(){const anchor=document.querySelector('.trust-row');if(!anchor||document.querySelector('.demo-trail'))return;const trail=node('div',undefined,'demo-trail');trail.innerHTML='<p>Try this first</p><ol><li><span>Scan a message</span><small>Use Payment & threat to see warning evidence.</small></li><li><span>Inspect a link</span><small>Switch to Link Lens and try Fake USCIS login.</small></li><li><span>Review recovery steps</span><small>Open the checklist for clicked, paid, or shared info.</small></li></ol>';anchor.after(trail);}
function enhanceRecoveryPlan(){const plan=$('#incident-plan');if(!plan)return;plan.classList.add('recovery-grid');plan.replaceChildren();for(const item of [{title:'If you clicked',body:'Close the page. Do not type a password. Run updates, change the affected password from a trusted device, and sign out of other sessions.'},{title:'If you paid',body:'Call your bank, card company, or payment app through its official number. Ask about stopping, reversing, or monitoring the transaction.'},{title:'If you shared a code',body:'Change the account password, turn on multi-factor authentication, remove unknown devices, and check recovery email and phone settings.'},{title:'If you gave personal info',body:'Save screenshots, watch accounts closely, report the incident, and warn family or coworkers so they do not use the same message or link.'}]){const card=node('article');card.append(node('h3',item.title),node('p',item.body));plan.append(card);}}
function updateCount(){const count=$('#count');count.textContent=`${field.value.length.toLocaleString()} / 10,000`;count.setAttribute('aria-label',`${field.value.length.toLocaleString()} of 10,000 characters`);}
function empty(){result.replaceChildren();const box=node('div',undefined,'empty'),mark=node('div','?','empty-mark');mark.setAttribute('aria-hidden','true');box.append(mark,node('h3',localized().emptyTitle),node('p',localized().emptyBody));result.append(box);}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200);}
async function copyText(text){try{await navigator.clipboard.writeText(text);}catch{const area=node('textarea');area.value=text;area.setAttribute('aria-hidden','true');area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw Error();}}
function focusResult(){result.focus({preventScroll:true});result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function riskCard(score,level,summary){const card=node('section',undefined,`risk-card ${level}`);card.innerHTML=`<p class="risk-kicker">RISK SIGNAL</p><strong class="risk-number">${score}</strong><span class="risk-out-of">/ 100</span><p class="risk-name">${level==='high'?'High':level==='review'?'Caution':'Low'}</p><div class="risk-bar"><div class="risk-fill" style="width:${score}%"></div></div><p class="risk-summary"></p>`;card.querySelector('.risk-summary').textContent=summary;return card;}
function explainScore(score,level){const copy=level==='high'?'Several signals are stacked together. Treat this as a stop sign until you verify somewhere else.':level==='review'?'One or more details deserve a pause. Verify through a source you choose yourself.':'Few warning signs were found here. Keep checking unexpected requests before you act.';const box=node('div',undefined,'score-note');box.append(node('h3','Why this result matters'),node('p',copy));return box;}
function shareButton(text,label='Copy message to share'){const wrap=node('div',undefined,'result-actions'),button=node('button',label,'quiet');button.type='button';button.addEventListener('click',async()=>{try{await copyText(text);toast('Share message copied.');}catch{toast('Could not copy. Select the message manually.');}});wrap.append(button);return wrap;}
function liveReputationButton(data){const wrap=node('div',undefined,'result-actions'),button=node('button','Check live reputation','quiet');button.type='button';button.addEventListener('click',async()=>{button.disabled=true;button.textContent='Checking live reputation...';try{const response=await fetch('/api/scan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:data.value})}),scan=await response.json();if(!response.ok)throw Error(scan.error||'Live scan is temporarily unavailable.');const liveScore=Math.min(100,data.score+(scan.unsafe?35:0)),level=levelFor(liveScore),summary=scan.unsafe?'Live reputation found: '+scan.threat.join(', ').replaceAll('_',' ').toLowerCase()+'.':'Live reputation found no known malware or phishing match.';result.replaceChildren(riskCard(liveScore,level,summary),explainScore(liveScore,level),node('div',scan.unsafe?'Do not open this link. Verify through a trusted website or phone number.':'No known threat match was returned. This is not a guarantee that the link is safe.',`result-banner ${level}`),linkDetails(data));const action=node('div',undefined,'next-step');action.innerHTML='<h3>What to do now</h3><ol><li>Never enter a password from an unexpected link.</li><li>Type the official address yourself.</li><li>Contact the sender through a trusted channel.</li></ol>';result.append(action);}catch(e){button.disabled=false;button.textContent='Try live check again';error.textContent=e.message;}});wrap.append(button);return wrap;}
function linkDetails(data){const labels=data.host.split('.').filter(Boolean),root=labels.slice(-2).join('.'),ending=labels.at(-1)??'',box=node('div',undefined,'domain-card');box.innerHTML='<h3>What site would receive you?</h3>';const dl=node('dl');for(const [term,value] of [['Actual host',data.host],['Registered domain',root||data.host],['Domain ending',ending?'.'+ending:'unknown']]){dl.append(node('dt',term),node('dd',value));}box.append(dl,node('p','Scammers often hide the real destination inside long names, short links, or words like secure, verify, login, or gov.','model-note'));return box;}
function evidenceQuote(text,evidence){const quote=node('blockquote',undefined,'evidence'),map=[];let clean='',offset=0;for(const char of text){const normalized=normalize(char);for(const part of normalized.split('')){clean+=part;map.push({start:offset,end:offset+char.length});}offset+=char.length;}const at=clean.indexOf(normalize(evidence));if(at<0){quote.textContent=evidence;return quote;}const start=map[at].start,end=map[at+normalize(evidence).length-1].end,left=Math.max(0,start-65),right=Math.min(text.length,end+85);quote.append(document.createTextNode((left?'...':'')+text.slice(left,start)),node('mark',text.slice(start,end)),document.createTextNode(text.slice(end,right)+(right<text.length?'...':'')));return quote;}
function renderMessage(data){const c=localized(),g=guidance[lang],score=Math.min(96,8+data.findings.length*18+(data.level==='high'?25:0)),level=data.level==='unknown'?'low':data.level,summary=data.findings.length?`Found ${data.findings.length} warning sign${data.findings.length===1?'':'s'} in the message wording.`:'No warning signs found in the message wording.';result.replaceChildren(riskCard(score,level,summary),explainScore(score,level));const box=node('div',undefined,`result-banner ${data.level}`);box.append(node('div',c[data.level==='review'?'reviewStatus':data.level],'status-label'),node('p',c[data.level+'Body']));result.append(box);if(data.findings.length){result.append(node('h3',c.findings),node('p',g.context,'helper'));const ul=node('ul',undefined,'findings');for(const finding of data.findings){const li=node('li');li.append(node('strong',c.labels[finding.id]??g.labels?.[finding.id]??finding.id),evidenceQuote(field.value,finding.evidence),node('p',g.reasons[reasonIds.indexOf(finding.id)]??'This pattern is commonly used to pressure people into unsafe action.','reason'));ul.append(li);}result.append(ul);}const action=node('div',undefined,'next-step');action.append(node('h3',c.next));const steps=data.level==='unknown'?[c.unknownAction]:actionSteps(data.findings,lang);if(data.level==='unknown')action.append(node('p',c.unknownAction));else{const list=node('ol');for(const step of steps)list.append(node('li',step));action.append(list);}const resultActions=node('div',undefined,'result-actions'),copyButton=node('button',c.copyPlan,'quiet');copyButton.type='button';copyButton.addEventListener('click',async()=>{try{await copyText(`${c.planHeading}\n\n${steps.map((step,index)=>`${index+1}. ${step}`).join('\n')}\n\n${c.planFooter}`);toast(c.copied);}catch{toast(c.copyFailed);}});resultActions.append(copyButton);action.append(resultActions);const help=node('details');help.append(node('summary',g.help));const link=node('a',g.recovery);link.href='https://consumer.ftc.gov/articles/what-do-if-you-were-scammed';link.target='_blank';link.rel='noopener noreferrer';help.append(link);action.append(help);result.append(action,shareButton('Please pause before clicking, paying, or sharing a code. Open the official website yourself or call a trusted number first. This message showed warning signs in VerifyBridge.'));if(data.findings.some(f=>['agency','domain','guarantee'].includes(f.id))){const official=node('div',undefined,'resource-card');official.append(node('h3',c.officialTitle),node('p',c.officialBody));const uscis=node('a',c.uscisResource);uscis.href='https://www.uscis.gov/avoid-scams';uscis.target='_blank';uscis.rel='noopener noreferrer';const ftc=node('a',c.resource);ftc.href='https://consumer.ftc.gov/articles/how-avoid-immigration-scams-and-get-real-help';ftc.target='_blank';ftc.rel='noopener noreferrer';official.append(uscis,ftc);result.append(official);}result.append(node('p',c[data.model.signal==='unavailable'?'modelUnavailable':data.model.signal==='scam-like'?'modelLike':'modelOther'],'model-note'));}
function inspectLink(shouldFocus=true){const data=localCheck(urlField.value),level=levelFor(data.score);result.replaceChildren(riskCard(data.score,level,'Link Lens inspected this address locally. It did not open the link.'),explainScore(data.score,level));const banner=node('div',level==='high'?'Do not click. Use a trusted website or phone number instead.':level==='review'?'Pause and verify using an address you find yourself.':'Few structural warnings found; this does not prove the link is safe.',`result-banner ${level}`);result.append(banner,linkDetails(data));if(data.signals.length){const list=node('ul',undefined,'findings');for(const signal of data.signals){const li=node('li');li.append(node('strong',signal.text),node('p',`Adds ${signal.points} points to the local risk signal.`,'reason'));list.append(li);}result.append(list);}const action=node('div',undefined,'next-step');action.innerHTML='<h3>What to do now</h3><ol><li>Do not enter a password from an unexpected link.</li><li>Type the official address yourself.</li><li>Contact the sender through a trusted channel.</li></ol><p class="model-note">Optional live reputation sends only this link to Google Web Risk through the VerifyBridge API.</p>';result.append(action,liveReputationButton(data),shareButton(`Please do not open this link yet: ${data.value}. Verify through the official website or a trusted phone number first.`, 'Copy link warning to share'));last=null;if(shouldFocus)focusResult();}
async function check(text){const data=analyze(text,model);field.value=text;updateCount();error.textContent='';last=data;renderMessage(data);focusResult();return data;}
function scheduleLiveScan(){clearTimeout(liveTimer);error.textContent='';const active=mode==='link'?urlField:field,value=active.value.trim();if(!value){lastLiveValue='';last=null;empty();return;}const minLength=mode==='link'?4:18;if(value.length<minLength){lastLiveValue='';last=null;empty();return;}liveTimer=setTimeout(()=>{if(value===lastLiveValue)return;try{if(mode==='link')inspectLink(false);else{const data=analyze(value,model);last=data;renderMessage(data);}lastLiveValue=value;error.textContent='';}catch(err){last=null;empty();if(err.message!=='empty')error.textContent=err.message==='long'?copy[lang].longError:err.message;}},550);}
function setLanguage(value){if(!Object.hasOwn(copy,value))throw Error('Unsupported language');lang=value;$('#language').value=value;document.documentElement.lang=value;$('#toast').classList.remove('show');const c=localized();document.querySelectorAll('[data-i]').forEach(el=>{if(c[el.dataset.i])el.textContent=c[el.dataset.i];});field.placeholder=c.placeholder;button.textContent=mode==='link'?c.linkButton:c.check;renderExamples();if(last)renderMessage(last);else empty();}
function renderExamples(){const box=$('#examples'),title=box.querySelector('p'),buttons=box.querySelector('div');buttons.replaceChildren();if(mode==='link'){title.textContent='Try a Link Lens demo';for(const [key,item] of Object.entries(linkExamples)){const button=node('button',item.label);button.type='button';button.dataset.linkExample=key;buttons.append(button);}}else{title.textContent=localized().try;for(const [key,label] of Object.entries({threat:copy[lang].exampleThreat,family:copy[lang].exampleFamily,routine:copy[lang].exampleRoutine})){const button=node('button',label);button.type='button';button.dataset.example=key;buttons.append(button);}}}
function setMode(value){mode=value;clearTimeout(liveTimer);lastLiveValue='';const c=localized();document.querySelectorAll('[data-mode]').forEach(el=>el.classList.toggle('active',el.dataset.mode===value));$('#message-wrap').classList.toggle('hidden',value==='link');$('#url-wrap').classList.toggle('hidden',value==='message');$('#examples').classList.remove('hidden');renderExamples();button.textContent=value==='link'?c.linkButton:c.check;error.textContent='';last=null;empty();}
form.addEventListener('submit',async event=>{event.preventDefault();error.textContent='';try{if(mode==='link')inspectLink();else await check(field.value);}catch(err){last=null;empty();error.textContent=err.message==='long'?copy[lang].longError:err.message==='empty'?copy[lang].emptyError:err.message;}});
field.addEventListener('input',()=>{updateCount();scheduleLiveScan();});
urlField.addEventListener('input',scheduleLiveScan);
$('#language').addEventListener('change',event=>setLanguage(event.target.value));
$('#clear').addEventListener('click',()=>{clearTimeout(liveTimer);field.value='';urlField.value='';last=null;lastLiveValue='';updateCount();error.textContent='';empty();(mode==='link'?urlField:field).focus();});
document.querySelectorAll('[data-mode]').forEach(el=>el.addEventListener('click',()=>setMode(el.dataset.mode)));
$('#examples').addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.example){setMode('message');void check(examples[lang][target.dataset.example]);}else if(target.dataset.linkExample){setMode('link');urlField.value=linkExamples[target.dataset.linkExample].url;inspectLink();}});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'check_scam_message',title:'Check a suspicious message',description:'Screen a message locally and display warning signs and next steps. Does not verify whether it is a scam.',inputSchema:{type:'object',properties:{message:{type:'string',minLength:1,maxLength:10000},language:{type:'string',enum:['en','es','vi','zh']}},required:['message'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.message!=='string'||!input.message.trim()||input.message.length>10000||Object.keys(input).some(k=>!['message','language'].includes(k))||(input.language!==undefined&&!Object.hasOwn(copy,input.language)))throw Error('Invalid message or language');if(input.language)setLanguage(input.language);return check(input.message);}})).catch(()=>{});}catch{}}
if(!document.querySelector('.guided-demo')){const demo=node('button','Show me how VerifyBridge works','guided-demo quiet');demo.type='button';demo.addEventListener('click',()=>{setMode('message');void check(examples.en.threat);toast('Demo started: review the warning, then try Link Lens.');});document.querySelector('.intro')?.append(demo);}
empty();
updateCount();
enhanceDemoPath();
enhanceRecoveryPlan();
extraCopy.en.try='Try an example';
extraCopy.es.try='Prueba un ejemplo';
renderExamples();
document.querySelectorAll('.scan-tab').forEach(tab=>{tab.setAttribute('role','tab');tab.setAttribute('aria-selected',tab.classList.contains('active')?'true':'false');tab.addEventListener('click',()=>document.querySelectorAll('.scan-tab').forEach(other=>other.setAttribute('aria-selected',other===tab?'true':'false')));});
const requestedDemo=new URLSearchParams(location.search).get('demo');if(requestedDemo==='message')setTimeout(()=>void check(examples.en.threat),250);if(requestedDemo==='link')setTimeout(()=>{setMode('link');urlField.value=linkExamples.fake.url;inspectLink(false);},250);if(requestedDemo==='recovery')setTimeout(()=>$('#incident-plan')?.scrollIntoView({block:'start'}),250);if(requestedDemo==='summary')setTimeout(()=>$('#summary-title')?.scrollIntoView({block:'start'}),250);
const missionCopy={
  en:{label:'Why VerifyBridge exists',title:'A safer pause before a risky decision',body:'Scams often rely on urgency, unfamiliar systems, and language barriers. VerifyBridge gives people a private place to inspect a message or link, understand the warning signs, and choose a safer next step.',privacy:'Private by design',privacyBody:'Core message and link checks run in the browser. No account is required, and message text is not saved or sent.',access:'Built for access',accessBody:'Clear explanations, four interface languages, mobile support, and practical recovery guidance help more people use cybersecurity tools.',creator:'Created by Alan Corona & Jacob Roberson',creatorBody:'Created by two Helpdesk Analyst I professionals and OU Tulsa cybersecurity students, for small businesses, nonprofits, families, and people who deserve clear, practical scam guidance.'},
  es:{label:'Por qué existe VerifyBridge',title:'Una pausa más segura antes de una decisión riesgosa',body:'Las estafas suelen aprovechar la urgencia, los sistemas desconocidos y las barreras del idioma. VerifyBridge ofrece un lugar privado para revisar un mensaje o enlace, entender las señales y elegir un paso más seguro.',privacy:'Privacidad desde el diseño',privacyBody:'Las revisiones principales se ejecutan en el navegador. No se necesita una cuenta y el texto no se guarda ni se envía.',access:'Creado para ser accesible',accessBody:'Explicaciones claras, cuatro idiomas, soporte móvil y orientación práctica permiten que más personas usen herramientas de ciberseguridad.',creator:'Creado por Alan Corona y Jacob Roberson',creatorBody:'Creado por dos profesionales de soporte técnico de nivel I y estudiantes de ciberseguridad de OU Tulsa, para pequeñas empresas, organizaciones sin fines de lucro, familias y personas que merecen orientación clara y práctica sobre estafas.'},
  vi:{label:'Lý do VerifyBridge tồn tại',title:'Một khoảng dừng an toàn trước quyết định rủi ro',body:'Lừa đảo thường lợi dụng sự khẩn cấp, hệ thống xa lạ và rào cản ngôn ngữ. VerifyBridge cung cấp nơi riêng tư để kiểm tra tin nhắn hoặc liên kết, hiểu dấu hiệu cảnh báo và chọn bước an toàn hơn.',privacy:'Riêng tư ngay từ thiết kế',privacyBody:'Việc kiểm tra cốt lõi chạy trong trình duyệt. Không cần tài khoản và nội dung tin nhắn không được lưu hoặc gửi đi.',access:'Thiết kế để dễ tiếp cận',accessBody:'Giải thích rõ ràng, bốn ngôn ngữ, hỗ trợ di động và hướng dẫn khôi phục giúp nhiều người tiếp cận công cụ an ninh mạng hơn.',creator:'Được tạo bởi Alan Corona và Jacob Roberson',creatorBody:'Được tạo bởi hai chuyên viên Helpdesk Analyst I và sinh viên an ninh mạng tại OU Tulsa, dành cho doanh nghiệp nhỏ, tổ chức phi lợi nhuận, gia đình và mọi người cần hướng dẫn rõ ràng, thiết thực về lừa đảo.'},
  zh:{label:'VerifyBridge 的使命',title:'在高风险决定前多一次安全停顿',body:'诈骗常利用紧迫感、陌生制度和语言障碍。VerifyBridge 提供私密空间，让用户检查消息或链接、理解警示信号并选择更安全的下一步。',privacy:'隐私优先设计',privacyBody:'核心消息和链接检查在浏览器中运行，无需账户，消息文本不会被保存或发送。',access:'为无障碍使用而构建',accessBody:'清晰说明、四种界面语言、移动设备支持和实用恢复指导，让更多人能使用网络安全工具。',creator:'由 Alan Corona 和 Jacob Roberson 创建',creatorBody:'由两位 Helpdesk Analyst I 专业人员及 OU Tulsa 网络安全专业学生创建，服务于小型企业、非营利组织、家庭，以及需要清晰实用防骗指导的人群。'}
};
function addMissionSection(){
  if(document.querySelector('.mission'))return;
  const footer=document.querySelector('footer'),section=node('section',undefined,'mission safety-hub');
  section.innerHTML='<div class="mission-lead"><p class="eyebrow" data-mission="label"></p><h2 data-mission="title"></h2><p data-mission="body"></p></div><div class="mission-grid"><article><h3 data-mission="privacy"></h3><p data-mission="privacyBody"></p></article><article><h3 data-mission="access"></h3><p data-mission="accessBody"></p></article><article class="creator-card"><h3 data-mission="creator"></h3><p data-mission="creatorBody"></p></article></div>';
  footer?.before(section);
  if(footer&&!footer.querySelector('.privacy-link')){const privacy=node('a','Privacy','privacy-link');privacy.href='./privacy.html';footer.append(privacy);}
  updateMission();
}
function updateMission(){const current=missionCopy[lang]||missionCopy.en;document.querySelectorAll('[data-mission]').forEach(element=>{element.textContent=current[element.dataset.mission];});}
