function addExtensionSection(){
  if(document.querySelector('.extension-guide'))return;
  const footer=document.querySelector('footer'),section=node('section',undefined,'extension-guide safety-hub');
  section.innerHTML='<div class="extension-lead"><p class="eyebrow" data-extension="label"></p><h2 data-extension="title"></h2><p data-extension="body"></p></div><ol class="extension-steps"><li><strong data-extension="setup"></strong><span data-extension="setupBody"></span></li><li><strong data-extension="load"></strong><span data-extension="loadBody"></span></li><li><strong data-extension="scan"></strong><span data-extension="scanBody"></span></li></ol><div class="extension-privacy"><h3 data-extension="privacy"></h3><p data-extension="privacyBody"></p><a href="https://github.com/jacobroberson9120/verifybridge/tree/main/extension" target="_blank" rel="noopener noreferrer" data-extension="repo"></a></div>';
  footer?.before(section);
  updateExtension();
}
function updateExtension(){const current=extensionCopy[lang]||extensionCopy.en;document.querySelectorAll('[data-extension]').forEach(element=>{element.textContent=current[element.dataset.extension];});}
